// Extract transaction data & validate fields
const payload = $input.first().json;
const data = payload.data || payload;
const description = data.description || '';
const amount = parseFloat(data.amount || 0);
const type = data.type || 'expense';
const category = data.category || 'Other';
const userId = payload.userId || data.userId;
const txId = payload.referenceId || data.transactionId;

// Basic categorization rules
const keywords = {
  Food: ['restaurant', 'cafe', 'coffee', 'pizza', 'burger', 'swiggy', 'zomato', 'food', 'groceries'],
  Transport: ['uber', 'lyft', 'taxi', 'fuel', 'petrol', 'parking', 'metro', 'bus', 'train'],
  Bills: ['electric', 'water', 'internet', 'wifi', 'utility', 'netflix', 'spotify', 'subscription'],
  Shopping: ['amazon', 'flipkart', 'store', 'mall', 'clothing', 'shoes', 'electronics'],
  Health: ['pharmacy', 'medicine', 'hospital', 'doctor', 'gym', 'fitness'],
  Salary: ['salary', 'payroll', 'wage', 'stipend', 'deposit']
};

let suggestedCategory = category;
if (!category || category === 'Other' || category === 'Uncategorized') {
  const lowerDesc = description.toLowerCase();
  for (const [cat, words] of Object.entries(keywords)) {
    if (words.some(w => lowerDesc.includes(w))) {
      suggestedCategory = cat;
      break;
    }
  }
}

// Anomaly check heuristic
const isAnomaly = type === 'expense' && (amount >= 10000 || (suggestedCategory === 'Food' && amount > 3000));
const severity = amount > 25000 ? 'high' : isAnomaly ? 'medium' : 'normal';

return [{
  json: {
    userId,
    transactionId: txId,
    description,
    amount,
    type,
    originalCategory: category,
    suggestedCategory,
    categoryUpdated: suggestedCategory !== category,
    isAnomaly,
    severity,
    logId: payload.logId,
    timestamp: new Date().toISOString()
  }
}];
